window.__HOT_STORIES__ = {"schemaVersion":1,"updatedAt":"2026-11-06T06:57:49.705Z","stories":{"4ff5060c-160a-4d65-bf28-706c0d53ec34":{"publicId":"4ff5060c-160a-4d65-bf28-706c0d53ec34","title":"OpenAI称AI管线单次运行修补948个Linux内核提权漏洞","status":"active","sourceCount":10,"reportCount":22,"firstReportAt":"2026-11-04T08:00:00.000Z","latestAt":"2026-11-05T23:22:55.767Z","latest":"OpenAI 发布网络安全模型 GPT-6 Cyber：ExploitGym 相对提升 51%，发现 Firefox 81 个新漏洞","digest":"OpenAI称其安全研究人员构建了一条自主漏洞发现、利用与修补管线，由一款网络安全模型驱动。在2026年10月中旬对最新Linux内核的一次运行中，管线从2,308个候选发现中验证1,724个漏洞，为291个信息泄露生成概念验证，并为948个不同的本地提权漏洞生成可用利用代码和候选补丁。OpenAI称这些利用代码在开启标准安全防护的原始Linux桌面配置上可运行，智能体还发现并使用了至少10种此前未知的Linux利用技术。\n\nOpenAI公布该次运行总API成本为1,213,430美元，平均每个本地提权漏洞约1,279美元；按其援引的Pwn2Own和TyphoonPWN赏金标准折算，这些漏洞的假设价值为1,890万至6,630万美元。OpenAI表示正与Linux维护者和Patch the Planet合作提交漏洞报告与补丁，人类研究人员会在上报前审查结果。\n\n上述漏洞数量、补丁效果、新型利用技术及成本均来自OpenAI的说法，尚未见独立验证。随后OpenAI发布网络安全模型GPT-6 Cyber，称其越界率从GPT-5.6 Cyber的约5%降至1%以下，目前向Daybreak Red项目的部分客户开放，未来数周扩大至该项目全部客户。OpenAI称该模型支撑了前述Linux内核研究。\n\n此外，Greg Brockman转发的内容称，该模型还在Firefox中发现111个渲染器RCE，其中81个为新漏洞，另有30个是开发者已知但被认为不可利用的漏洞的可利用利用程序。","digestUpdatedAt":"2026-11-05T23:31:48.106Z","reports":[{"id":"gzzyv7qj81q0vfomoqf3vnpvk","title":"OpenAI 发布网络安全模型 GPT-6 Cyber：ExploitGym 相对提升 51%，发现 Firefox 81 个新漏洞","summary":"OpenAI 于 11 月 5 日宣布推出网络安全专用模型 GPT-6 Cyber，在 ExploitGym 基准得分 48.5%，较 GPT-5.6 Cyber 的 32.1% 相对提升约 51%。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-05T23:22:55.767Z","url":"https://www.ithome.com/1/023/038.htm"},{"id":"e64te9342kqavaw37c3562iyj","title":"OpenAI 发布 GPT-6 Cyber 漏洞挖掘模型，被评为最高网络风险等级","summary":"OpenAI 发布 GPT-6 Cyber，一个用于在授权目标内发现和利用软件漏洞的安全研究模型，目前仅向部分获批的 Daybreak Red 客户开放，可通过 API 和 Codex 使用。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-05T22:27:59.000Z","url":"https://x.com/rohanpaul_ai/status/2118470407313646054"},{"id":"r9wqapvpymgipbdvnjkdcf5v5","title":"OpenAI 发布 GPT-6 Cyber，可发现漏洞、构建利用并提出修复","summary":"OpenAI 推出专注挖掘软件安全漏洞的 GPT-6 Cyber，称其可发现缺陷、构建可用 exploit 并建议补丁；在 ExpitGym 上得分 48.5%，高于前代 GPT-5.6 Cyber 的 32.1%，无安全指令时 99.93% 的情况未越界。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-05T20:36:25.000Z","url":"https://the-decoder.com/openais-gpt-6-cyber-can-both-break-into-systems-and-propose-how-to-fix-them/"},{"id":"t46wno4380azfycpjyu3ygqr3","title":"OpenAI 发布网络安全模型 ChatGPT Cyber，此前 GPT 5.6 Sol 帮助发现 Ubuntu 严重漏洞","summary":"OpenAI 宣布向攻击性网络安全项目 Daybreak Red 的最高级别用户开放专注网络安全的新模型 ChatGPT Cyber。此前 Charge Robotics 联合创始人 Max Justicz 用 GPT 5.6 Sol 在约 2 小时内发现 Ubuntu 相关代码库的严重漏洞，Debian Project 已发布补丁且暂无被利用迹象。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-05T19:06:12.000Z","url":"https://techcrunch.com/2026/11/05/openai-released-a-new-cybersecurity-model-is-that-enough/"},{"id":"vcgonzjl8t9ooof5bgjgh8ta5","title":"OpenAI 团队用网络安全模型扫描开源项目，发现 Firefox 111 个渲染器 RCE","summary":"Greg Brockman 转发并称赞团队的网络安全模型工作。被引用内容称，该模型除发现 948 个 Linux 漏洞外，还在 Firefox 中发现 111 个渲染器 RCE，其中 81 个为新漏洞，另有 30 个是开发者已知但被认为不可利用的漏洞的可利用利用程序。团队正用该技术扫描更多开源项目以维护互联网基础设施，并表示这只是开始。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-05T18:14:30.000Z","url":"https://x.com/gdb/status/2118406616240562601"},{"id":"jia4e5zq0bruh4hg2v9qovgj6","title":"OpenAI 发布安全专用模型 GPT-6 Cyber，通过 Daybreak Red 开放","summary":"OpenAI 发布安全专用模型 GPT-6 Cyber，称其在多个网络安全用例上表现突出，并强调能力提升的同时对齐更好。该模型此前驱动了已公布的 Linux 内核研究，Mozilla、Palo Alto Networks、Calif、Cisco 及 OpenAI 自身的安全团队已在使用，目前向部分 Daybreak Red 客户开放，访问范围将逐步扩大。","sourceName":"X：Tibo (@thsottiaux)","firstParty":true,"publishedAt":"2026-11-05T17:56:34.000Z","url":"https://x.com/thsottiaux/status/2118402103907655903"},{"id":"n2jeoklrm9bd1q6okh5behxe4","title":"OpenAI 发布 GPT-6 Cyber 安全研究模型并推出 Daybreak Red for Critical Infrastructure","summary":"OpenAI 发布面向安全研究的 GPT-6 Cyber，称其能力更强且对齐更好，已用于 Linux kernel、Firefox 等安全关键软件的防御研究，Mozilla、Palo Alto Networks、Calif、Cisco 及 OpenAI 自家安全团队已在使用。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-05T17:31:11.000Z","url":"https://x.com/gdb/status/2118395717966606542"},{"id":"nqbrlejqkzva8zscy5y7h4afq","title":"OpenAI 发布 GPT-6 Cyber 安全研究模型","summary":"OpenAI 发布 GPT-6 Cyber，定位为安全研究方向的模型，在更强能力的同时改进模型对齐。该模型支撑了此前公布的 Linux 内核研究，Mozilla、Palo Alto Networks、Calif、Cisco 及 OpenAI 自己的安全团队已在使用。目前向部分 Daybreak Red 客户开放，并将逐步扩大访问范围。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-05T17:09:13.000Z","url":"https://x.com/OpenAI/status/2118390190246879554"},{"id":"gvh1epp54d40ck03kruj008w4","title":"OpenAI 发布 GPT-6 Cyber 网络安全模型，越界率降至 1% 以下","summary":"OpenAI 发布网络安全模型 GPT-6 Cyber，称其更擅长发现漏洞且更不易越界攻击其他平台，测试中越界率从 GPT-5.6 Cyber 的约 5% 降至 1% 以下。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-05T17:00:00.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1027599/openai-gpt-6-cyber-launch"},{"id":"u904yv6dn7sw6lwjgxxedqd3b","title":"OpenAI 发布 GPT-6 Cyber 网络安全模型","summary":"OpenAI 发布网络安全模型 GPT-6 Cyber，针对漏洞发现、验证与修复训练，并通过 Daybreak Red/Blue 平台向审核通过的安全团队开放。","sourceName":"OpenAI：官网动态（RSS · 排除企业/客户案例）","firstParty":true,"publishedAt":"2026-11-05T09:00:00.000Z","url":"https://openai.com/index/introducing-gpt-6-cyber"},{"id":"fhmh7s1sb3p0j4yx8k3wiqj0n","title":"Latent Space AINews 周报：Kimi K3.1 Pro 开源、OpenAI 自主管道修复 948 个 Linux 漏洞等一周动态","summary":"Latent Space AINews 汇总 2026-11-03 至 11-04 的 AI 动态：OpenAI 用自主漏洞管道验证并生成 948 个 Linux 内核本地提权漏洞补丁，API 成本约 $1.2M；Moonshot 开源 Kimi K3.1 Pro（2.8T 总参数、104B 激活、1M 上下文）。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-05T06:24:09.000Z","url":"https://latent.space/p/ainews-it-s-swapping-season/"},{"id":"p32adef843yhcx45oc7qf4p5a","title":"OpenAI 称其安全模型一次运行修复 948 个 Linux 内核提权漏洞，API 成本约 120 万美元","summary":"OpenAI 展示其自主漏洞发现、利用与修复管线，用即将发布的网络模型一次运行验证并生成 948 个 Linux 内核本地提权漏洞补丁，总 API 成本 120 万美元。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-05T01:06:09.000Z","url":"https://x.com/rohanpaul_ai/status/2118147825146175666"},{"id":"vepefw88ym7jdtjr7l9pp8mit","title":"OpenAI 团队用网络模型单次运行验证并修补 Linux 内核 948 个本地提权漏洞","summary":"OpenAI 安全研究人员构建了自主化的漏洞发现、利用与修补流水线，作者 Tibo 转发该成果并表示团队将在未来数月分享更多工作。一次运行中，即将推出的网络模型验证并为 Linux 内核 948 个本地提权漏洞生成了补丁，总 API 成本 120 万美元；漏斗图显示流程从 2308 个候选发现开始，还得到 291 个可工作的 PoC。","sourceName":"X：Tibo (@thsottiaux)","firstParty":true,"publishedAt":"2026-11-05T01:02:03.000Z","url":"https://x.com/thsottiaux/status/2118146794362405231"},{"id":"yp5w29mewvpwgst44zr9lms6n","title":"OpenAI 前沿网络安全模型一周发现约 1000 个 Linux 本地提权漏洞","summary":"OpenAI 将大量前沿算力用于免费发现并修补开源代码库漏洞。其即将推出的前沿网络安全模型在一周内、约 $1M token 成本下，在 Linux 内核发现约 1000 个本地提权（LPE）漏洞，并发现至少 10 类新的 Linux 利用技术；作为对比，以前安全研究者通常每年在 Linux 中发现约 20 个 LPE 漏洞。Greg Brockman 转发该项目补充说明，称 Linux 内核是 OpenAI 尤为关键的软件。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-04T23:54:59.000Z","url":"https://x.com/gdb/status/2118129916923568345"},{"id":"n87esnpsqi71pcdxtda9bs88x","title":"OpenAI 用网络漏洞管线发现并修复 Linux 内核 948 个本地提权漏洞","summary":"OpenAI 安全研究团队构建了自主的网络漏洞发现、利用与修补管线，用一款即将推出的网络模型在单次运行中验证并生成补丁，覆盖 Linux 内核 948 个本地提权漏洞，总 API 成本约 120 万美元，约每个漏洞 1000 美元。漏斗数据显示从 2308 个候选发现出发，1724 个通过验证，最终得到 948 个可用的 LPE exploit 和 291 个可用的 PoC。Greg Brockman 称这是显著加固开源及专有项目的一种可规模化新路径。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-04T23:53:31.000Z","url":"https://x.com/gdb/status/2118129547443056763"},{"id":"rzg5qe1722k37dqkaij0o3xpf","title":"OpenAI 与 Linux 维护者及 Patch the Planet 合作发现并修复漏洞","summary":"OpenAI 表示其目标是帮助防御者在攻击者利用之前发现并修复漏洞，正在与 Linux 维护者和 Patch the Planet 合作伙伴合作提交漏洞报告和补丁，详情见 openai.com/index/a-thousand-fewer-paths-to-root/。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:13:27.000Z","url":"https://x.com/OpenAI/status/2118119463161905362"},{"id":"cg5nvdwb8nb0ipb77ip0teetw","title":"OpenAI 公布 AI 挖掘本地提权漏洞成本：约 $1,279 一个漏洞","summary":"OpenAI 公布一次漏洞挖掘运行的数据：全程 API 调用花费 $1,213,430，平均每个本地提权（local privilege escalation）漏洞成本约 $1,279。按历史 Pwn2Own 和 TyphoonPWN 赏金标准折算，这些漏洞的假设价值为 $18.9M–$66.3M，OpenAI 据此认为防御方应主动用 AI 分析软件，使网络攻击的成本高到难以承受。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:13:26.000Z","url":"https://x.com/OpenAI/status/2118119459772862490"},{"id":"fzfo43bb8rx5gv2jx64fx5ikl","title":"OpenAI 展示模型复现 1,724 个漏洞并生成 948 个本地提权可用 exploit","summary":"OpenAI 介绍一次运行复现了 1,724 个漏洞，为 291 个信息泄露生成了概念验证，并为 948 个不同的本地提权漏洞生成了可用 exploit。这些 exploit 在开启标准安全防护的原始 Linux 桌面配置上可以运行。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:13:26.000Z","url":"https://x.com/OpenAI/status/2118119458149634360"},{"id":"ulr0gn1mg4kpj7yz2h2zwp7u1","title":"OpenAI 称其智能体发现至少 10 种新型 Linux 漏洞利用技术","summary":"OpenAI 称其智能体发现并使用了至少 10 种新型 Linux 漏洞利用技术，据其及所咨询专家所知均为此前未知的。OpenAI 认为这表明前沿大语言模型能发现并修补新的漏洞利用方式，而不只是套用已知技术。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:13:26.000Z","url":"https://x.com/OpenAI/status/2118119461345739018"},{"id":"cgpfrzh42igdn9vhtxidgoxht","title":"OpenAI 自动化漏洞发现与修复流程","summary":"该流程会找出与安全相关的代码，扫描漏洞，在隔离环境中复现漏洞，测试漏洞是否可被利用，并生成候选补丁。\n\n人类研究人员在报告漏洞和向维护者提出修复方案之前会先审查结果。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:13:25.000Z","url":"https://x.com/OpenAI/status/2118119454681006460"},{"id":"hpcrwpvdv9exm8hsd7cp9mk4c","title":"OpenAI 展示自主漏洞发现与修补管线，一次运行生成 948 个 Linux 内核本地提权漏洞补丁","summary":"OpenAI 安全研究人员构建了自主的网络漏洞发现、利用与修补管线，用一款即将推出的网络安全模型在单次运行中验证并为 Linux 内核 948 个本地提权漏洞生成补丁，总 API 成本 120 万美元。漏斗数据显示：2,308 个候选发现中 1,724 个通过验证，最终得到 948 个可用的 LPE exploit 和 291 个可用的 PoC。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:13:24.000Z","url":"https://x.com/OpenAI/status/2118119451401048497"},{"id":"ewubpx7n7eojfvgdx6bbrd7vl","title":"OpenAI 用 cyber 模型自动化挖掘并修补 948 个 Linux 内核本地提权漏洞","summary":"OpenAI 构建了一条由即将推出的 cyber 模型驱动的漏洞发现、验证、利用评估与补丁生成流水线，于 2026 年 10 月中旬对最新 Linux 内核的一次运行中复现 1,724 个漏洞，生成 948 个本地提权（LPE）漏洞利用及对应补丁，总 API 成本 $1,213,430，平均每个 LPE $1,279。","sourceName":"OpenAI：官网动态（RSS · 排除企业/客户案例）","firstParty":true,"publishedAt":"2026-11-04T08:00:00.000Z","url":"https://openai.com/index/a-thousand-fewer-paths-to-root"}]},"e765b639-baae-42e1-8cb8-b76d31655219":{"publicId":"e765b639-baae-42e1-8cb8-b76d31655219","title":"Google 发布 Omni 1.2 Flash，视频生成提至 15 秒","status":"active","sourceCount":15,"reportCount":22,"firstReportAt":"2026-11-05T17:00:00.000Z","latestAt":"2026-11-06T02:29:44.000Z","latest":"Higgsfield 上线 Gemini Omni 1.2 Flash","digest":"Google DeepMind 发布视频生成与编辑模型 Gemini Omni 1.2 Flash，原生片段上限从 10 秒提升到 15 秒，并支持在 3 秒到 15 秒之间指定任意时长。720p 视频 API 价格较 Omni 1.1 下降 30% 至每秒 0.07 美元；草稿可在 360p 或 720p 生成，再放大到 1080p 或 4K。模型从发布当日起在 Gemini API、Google Cloud、Flow、Google Vids、Google Ads 和 Google AI Studio 推出。\n\n在 Gemini App 中，该模型面向所有 Google AI 订阅用户开放，但 15 秒片段仅限 Ultra 订阅者；Google 称在 Google Vids 中生成 15 秒片段不额外收费。第三方平台 fal、OpenRouter、Krea 和 Higgsfield 也同步上线该模型，OpenRouter 按分辨率分档计价，360p 每秒 0.023 美元、720p 0.070 美元、1080p 0.104 美元、4K 0.209 美元，并称与直连价格相同。\n\nGoogle 称，新模型改进了场景随时间的一致性、多说话人口型同步和镜头连续性，减少跳切，并支持在对话中逐轮替换背景、主体或光照，无需从头重来；这些效果来自 Google 的演示与说法。Arena 随后公布，该模型在 Text-to-Video 和 Image-to-Video 榜单首秀即排名第一，文生视频得分 1541 分，比 Omni 1.1 Flash 高 27 分。","digestUpdatedAt":"2026-11-06T02:53:01.173Z","reports":[{"id":"dh6u0rf9omkdcu6qj7j7m65j4","title":"Higgsfield 上线 Gemini Omni 1.2 Flash","summary":"立即试用 Gemini Omni 1.2 Flash：\n\nhttps://higgsfield.ai/ai/video?model=gemini-omni-flash-1-2","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-06T02:29:44.000Z","url":"https://x.com/higgsfield/status/2118531248058712439"},{"id":"iherxwf5l55jl8x0akk22gx2j","title":"Gemini Omni 1.2 Flash 上线 Higgsfield","summary":"Gemini Omni 1.2 Flash 已在 Higgsfield 上线。\n\n15 秒片段，角色一致，最高 4K，带原生音频。\n\n现已在 Higgsfield 可用。","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-06T02:29:44.000Z","url":"https://x.com/higgsfield/status/2118531245865087363"},{"id":"e13mz24869h24423kxt65guy0","title":"Gemini Omni 1.2 Flash 上线 Krea","summary":"Gemini Omni 1.2 Flash 现已在 Krea 上线。\n\n15 秒片段、更深入的电影级控制，以及多轮编辑！\n\n立即试用 👇","sourceName":"X：Krea AI (@krea_ai)","firstParty":false,"publishedAt":"2026-11-06T01:00:12.000Z","url":"https://x.com/krea_ai/status/2118508716261810321"},{"id":"ubd0353yy2s8rtssyi3kymw2s","title":"Google 发布 Gemini Omni 1.2 Flash：15 秒视频生成，720p 每秒 $0.07","summary":"Google 发布视频生成与编辑模型 Gemini Omni 1.2 Flash，原生片段时长从 10 秒延长到 15 秒，720p 价格降至 $0.07/秒，比 Omni 1.1 Flash 便宜约 30%，一段 15 秒 720p 视频约 $1.05。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-05T22:58:21.000Z","url":"https://www.marktechpost.com/2026/11/05/google-gemini-omni-1-2-flash-15-second-video/"},{"id":"nmtokg17qo3e8nzni5n8412eq","title":"谷歌发布 Gemini Omni 1.2 Flash 视频模型，原生 15 秒生成、较 1.1 降价 30%","summary":"谷歌正式推出 Gemini Omni 1.2 Flash 视频生成模型，在 Gemini API 与 Gemini for business 平台开放使用。新版支持原生 15 秒生成（可在 3 到 15 秒按 1 秒自定义）、多轮对话式编辑与更强的参考遵循能力；720p 价格为每秒 0.07 美元，较 1.1 版本降价 30%。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-05T22:44:52.020Z","url":"https://www.ithome.com/1/023/026.htm"},{"id":"xy1yt88rms0nnj4nlyi1m0m3y","title":"Gemini Omni 1.2 Flash 上线 OpenRouter：15 秒视频、360p 到 4K、定价较 1.1 低约 30%","summary":"OpenRouter 宣布 Google 的视频模型 Gemini Omni 1.2 Flash 上线，支持最长 15 秒片段（1.1 为 10 秒）、360p 至 4K、16:9 或 9:16、原生音频，每秒定价比 1.1 低约 30%。定价为 360p $0.023/秒、720p $0.070/秒、1080p $0.104/秒、4K $0.209/秒；同一模型在 chat completions 上还能处理文本、图像和视频输入（131K 上下文，$1.50/M 输入，$9/M 输出），价格与直连相同。","sourceName":"X：OpenRouter (@OpenRouter)","firstParty":false,"publishedAt":"2026-11-05T20:29:52.000Z","url":"https://x.com/OpenRouter/status/2118440685510779289"},{"id":"pp4a8xihgan2yi22okp0uh588","title":"Google Gemini Omni Flash v1.2 视频模型上线 fal 平台，提供文生视频等六种能力入口","summary":"fal 宣布 Google gemini-omni-flash v1.2 在其平台开放试用，提供 Text-to-Video、Image-to-Video、Reference-to-Video、Edit、Extend、Upscale 六个功能的入口链接。","sourceName":"X：fal (@fal)","firstParty":false,"publishedAt":"2026-11-05T19:42:50.000Z","url":"https://x.com/fal/status/2118428845804003420"},{"id":"p9n5i4o8i3yw1kdsilowe5nba","title":"Google Gemini Omni Flash 1.2 上线 fal 平台","summary":"Google 的 Gemini Omni Flash 1.2 现已上线 fal 平台。该模型可从文本、图片或参考片段生成带原生音频的视频，用自然语言指令剪辑现有素材，为视频追加 3 到 10 秒续段，并支持将片段放大至 1080p 或 4K，输出最长 15 秒。","sourceName":"X：fal (@fal)","firstParty":false,"publishedAt":"2026-11-05T19:42:49.000Z","url":"https://x.com/fal/status/2118428843937497579"},{"id":"mrcjnhlrgus9fp09akj6ynarx","title":"Gemini Omni 1.2 Flash 登顶 Arena 文生视频榜第一","summary":"Arena 宣布 Google 的 Gemini Omni 1.2 Flash 在 Text-to-Video 和 Image-to-Video 榜单首秀即排名第一，Video Edit 排第三。其文生视频得分为 1541 分，比上一代 Gemini Omni 1.1 Flash 的 1514 分高出 27 分，Google 的 Omni 系列就此包揽文生视频榜前三。被引用的 Google 介绍称，该模型视频生成和编辑时长上限提升到 15 秒，720p 视频 API 价格降至每秒 $0.07，并改进了场景一致性和角色语音。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-05T19:08:37.000Z","url":"https://x.com/arena/status/2118420238756921648"},{"id":"vlkb8bkscrqwm2l834futbvnw","title":"Google Gemini Omni 1.2 Flash 正式可用，视频延长至 15 秒并降价 30%","summary":"Google DeepMind 宣布 Gemini Omni 1.2 Flash 视频生成模型正式全面开放，剪辑时长从最长 10 秒提升到 15 秒，720p 视频价格降至每秒 $0.07，降价 30%。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-05T19:05:31.000Z","url":"https://the-decoder.com/googles-gemini-omni-1-2-flash-stretches-ai-video-clips-to-15-seconds-and-cuts-pricing-by-30-percent/"},{"id":"jqdxjye2368l1e8kxy6zpsn7d","title":"Gemini Omni 1.2 Flash 视频模型上线，支持多轮对话式编辑与 15 秒生成","summary":"Google Gemini 宣布 Gemini Omni 1.2 Flash 视频生成模型即日起向所有 Google AI 订阅者推送，Gemini 应用内支持多轮对话式剪辑和更稳定的画面。Google AI Ultra 订阅者可单次生成并编辑最长 15 秒的视频；该模型由 Google DeepMind 更新，可先以 360p 或 720p 草稿（$0.07/s，成本低 30%）再放大至 1080p 或 4K，支持 3s 到 15s 任意时长、更自然的多人对话口型同步和更连贯的运镜。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-05T18:12:57.000Z","url":"https://x.com/GeminiApp/status/2118406227533435391"},{"id":"b9r6mce1w285jcj57aacm6425","title":"Google 发布 Gemini Omni Flash 1.2，支持 15 秒视频生成并降价 30%","summary":"Logan Kilpatrick 宣布 Gemini Omni Flash 1.2 正式推出，视频生成时长提升至 15 秒，并新增相机视角的更深电影级控制与多轮对话编辑支持。模型还减少了视觉漂移，价格比 Omni Flash 1.1 低 30%，详情见 https://blog.google/innovation-and-ai/technology/developers-tools/introducing-gemini-omni-1-2-flash/。","sourceName":"X：Logan Kilpatrick (@OfficialLoganK)","firstParty":false,"publishedAt":"2026-11-05T17:11:48.000Z","url":"https://x.com/OfficialLoganK/status/2118390838434693281"},{"id":"nrkaqf466y46q79oh7bg40x9w","title":"Gemini Omni 1.2 Flash 在 Gemini API 和 Google AI Studio 发布，价格下调 30%","summary":"Gemini Omni 1.2 Flash 在 Gemini API 和 Google AI Studio 发布，支持 15 秒视频片段，改进对话式视频编辑和一致性。速度保持不变，720p 价格下调 30% 至 $0.07/s。","sourceName":"X：Philipp Schmid（Google DeepMind 开发者体验） (@_philschmid)","firstParty":false,"publishedAt":"2026-11-05T17:11:33.000Z","url":"https://x.com/_philschmid/status/2118390774442164501"},{"id":"uiqo0uz71htno0vwtpwty6wv7","title":"Google 发布 Gemini Omni 1.2 Flash，覆盖 Google Cloud、Gemini API 等多款产品","summary":"Google 宣布 Gemini Omni 1.2 Flash 从今日起在 Google Cloud、Flow、Google Vids、Google Ads、Google AI Studio 和 Gemini API 上推出。同时面向所有 Google AI 订阅者开放 Gemini App，Ultra 订阅者可生成 15 秒片段。详情见 http://goo.gle/4kzWTi3。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-05T17:10:07.000Z","url":"https://x.com/Google/status/2118390413870412082"},{"id":"dtbrbtf4gw0cj0oaz0f69ucjw","title":"Google 演示视频生成的多轮对话式修改","summary":"Google 演示视频生成可通过多轮对话逐步修改同一片段，无需从头重来。示例中 Turn 1 生成一只波纹效果的章鱼，Turn 2 的后续提示词将主角换成一位舞者，裙摆精确复刻原有动作。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-05T17:10:06.000Z","url":"https://x.com/Google/status/2118390412184363108"},{"id":"o6qnpazaa8zowl20g11stp91s","title":"Omni 1.2 Flash 生成15秒蜂巢讲解视频","summary":"生成最长 15 秒的片段。\n\n从单个风格帧出发，Omni 1.2 Flash 在蜂巢内生成一段四镜头、15 秒的微距讲解视频，标注文字拼写准确并带有运动跟踪 🐝","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-05T17:10:06.000Z","url":"https://x.com/Google/status/2118390410460454975"},{"id":"bk8tmmv13uertmfs8z5ydjrxy","title":"Google DeepMind 发布视频生成模型 Gemini Omni 1.2 Flash","summary":"Google 发布来自 Google DeepMind 的更新视频生成模型 Gemini Omni 1.2 Flash。草稿可在 360p 或 720p 生成（$0.07/s）再放大到 1080p 或 4K，成本降低 30%；支持生成与编辑最长 15s 的视频，可指定 3s 到 15s 的任意时长，并支持在对话中逐轮替换背景、主体或光照，多说话人对话口型更同步，镜头连续运镜减少跳切。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-05T17:10:05.000Z","url":"https://x.com/Google/status/2118390406316728555"},{"id":"f4khtbflsh6wm6pu9ybsf67wu","title":"Omni 1.2 Flash 场景一致性提升","summary":"相比 Omni 1.1，在角色、物体和场景一致性上更强。\n\n给定相同的静态海报和提示词，Omni 1.2 Flash 逐层构建场景，同时让每一处玻璃质感、阴影和字体细节在最后一帧都保持一致 💡","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-05T17:10:05.000Z","url":"https://x.com/Google/status/2118390408665309462"},{"id":"n8indhlghj0ljiyr5j1s0cegz","title":"Google 开放 Gemini Omni 1.2 Flash 使用入口，覆盖 Flow、Vids、Gemini App 和 AI Studio","summary":"Google AI 官宣 Gemini Omni 1.2 Flash 开放使用：创作者可在 Google Flow（推出中）、Google Vids 和 Gemini App 生成视频，Gemini App 面向所有 Google AI 订阅用户推出，Ultra 订阅可生成 15 秒片段。开发者可在 AI Studio 原型验证，企业可在 Gemini for Business 试用 Omni 并在 Google Ads 扩展投放。详情见 blog.google 的发布文章。","sourceName":"X：Google AI (@GoogleAI)","firstParty":false,"publishedAt":"2026-11-05T17:08:19.000Z","url":"https://x.com/GoogleAI/status/2118389964056547374"},{"id":"qpypeaufuxedxrma4p471r74m","title":"Google 发布 Gemini Omni 1.2 Flash，视频生成上限提升至 15 秒并降价 30%","summary":"Google 发布 Gemini Omni 1.2 Flash，视频生成与编辑上限提升至 15 秒，API 价格较上一代下降 30%，720p 视频每秒 0.07 美元。模型改进了场景时间一致性、角色语音流畅度，减少跳切等视觉瑕疵，并更忠实于上传的参考素材；用户可在 Flow、Google Vids 和 Gemini App 中使用，作者还演示了将单张风格帧生成 4 镜头 15 秒蜂巢科普视频。","sourceName":"X：Google AI (@GoogleAI)","firstParty":false,"publishedAt":"2026-11-05T17:08:19.000Z","url":"https://x.com/GoogleAI/status/2118389961426874879"},{"id":"tna7e11amxlispk71gj6hwsi6","title":"Google DeepMind 发布 Gemini Omni 1.2 Flash，支持 15 秒视频生成并降价 30%","summary":"Google DeepMind 发布 Gemini Omni 1.2 Flash，在 Gemini API 和 Gemini for business 全面开放，首次实现 Gemini Omni 全面可用。","sourceName":"Google DeepMind：Blog（RSS）","firstParty":true,"publishedAt":"2026-11-05T17:05:16.000Z","url":"https://deepmind.google/blog/gemini-omni-12-flash-fast-and-cost-effective-with-longer-clips/"},{"id":"yjwroxww17lcg4ntcu9ruo105","title":"Google 发布 Gemini Omni 1.2 Flash：15 秒视频生成，降价 30% 至 $0.07/秒","summary":"Google 发布 Gemini Omni 1.2 Flash，在 Gemini API 和 Gemini for business 全面开放。新模型原生支持最长 15 秒视频生成（此前为 10 秒），支持多轮对话编辑和更强的参考图一致性，价格较 1.1 下降 30% 至 720p 视频 $0.07/秒。","sourceName":"Google Blog：AI（RSS）","firstParty":true,"publishedAt":"2026-11-05T17:00:00.000Z","url":"https://blog.google/innovation-and-ai/technology/developers-tools/introducing-gemini-omni-1-2-flash/"}]},"37046dc2-8e44-4949-965c-ef07dbd0b13e":{"publicId":"37046dc2-8e44-4949-965c-ef07dbd0b13e","title":"OpenAI 发布 Images 2.6：ChatGPT 可生成 GIF，API 上线两款模型","status":"active","sourceCount":13,"reportCount":20,"firstReportAt":"2026-11-04T00:00:00.000Z","latestAt":"2026-11-05T07:03:17.000Z","latest":"OpenAI 发布 GPT-Image-2.6 Flare 与 Sunburst，新增 GIF、SVG 导出和 6 秒生成","digest":"OpenAI 发布 Images 2.6，ChatGPT 首次能直接生成 GIF 动图：用户可用提示词或上传图片生成，并调整播放速度、逐帧编辑和分享。该功能随 Images 2.6 向所有套餐的 ChatGPT 和 Codex 用户推送，覆盖网页、桌面和移动端；新版还支持保存人物、宠物或角色的参考图，供后续创作复用。\n\nAPI 同步上线两款图像模型：GPT-Image-2.6 Flare 主打速度，low 画质下最快 6 秒出图；GPT-Image-2.6 Sunburst 主打中高质量与多次编辑间的细节一致性。OpenAI 称两者生成速度比前代快 50%，并支持图像标记与 SVG 导出。据 MarkTechPost 引述模型页面，两款模型按 token 计费且价格相同：文本输入每百万 token 5 美元、图像输入 8 美元、图像输出 30 美元，调整复杂度不另收费。\n\n性能数据存在不同口径：OpenAI 引用的 DesignArena 数据称 Sunburst 在 Image Arena 排名第一、Flare 比前代快 2.6 倍；Arena 随后公布 Sunburst（Medium）在文生图榜排第 2、Flare（Medium）排第 4，并称新模型比 2.5 快 2 倍以上、最低延迟约 5 秒。fal 和 Higgsfield 等第三方平台也已上线该模型，Higgsfield 对 Pro、Plus、Max、Ultra 套餐的新用户提供 7 天无限使用。","digestUpdatedAt":"2026-11-05T08:37:00.041Z","reports":[{"id":"mcab7bd12n30tbwsd97xqpizh","title":"OpenAI 发布 GPT-Image-2.6 Flare 与 Sunburst，新增 GIF、SVG 导出和 6 秒生成","summary":"OpenAI 在 ChatGPT、Codex 和 API 上线 Images 2.6，API 端分为 GPT-Image-2.6 Flare 和 Sunburst 两个模型，官方称生成速度比此前快 50%，Flare 在低质量下最快 6 秒出图。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-05T07:03:17.000Z","url":"https://www.marktechpost.com/2026/11/04/openai-gpt-image-2-6-flare-sunburst/"},{"id":"eoav9ea3p1g5xhf2a57dga4nx","title":"ChatGPT Images 2.6 发布，新增 GIF 与参考图功能","summary":"Greg Brockman 转发 OpenAI 公告宣布 ChatGPT Images 2.6 上线。新版本支持 GIF 和参考图像，另有两款新模型将进入 API，图像生成速度提升 50%。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-05T02:54:05.000Z","url":"https://x.com/gdb/status/2118174986544488876"},{"id":"rxbccxa9of5e3e4v07auo0kmp","title":"OpenAI 发布 ChatGPT Images 2.6，支持生成动图和复用参考图","summary":"OpenAI 发布 ChatGPT Images 2.6，可将提示词和图片生成动画 GIF。新版本还支持保存自己、宠物和角色的参考图，在新创作中直接复用而无需重复上传。Images 2.6 当天起面向所有套餐开放，覆盖网页、桌面和移动端的 ChatGPT 与 Codex。","sourceName":"X：ChatGPT (@ChatGPT)","firstParty":false,"publishedAt":"2026-11-05T02:27:14.000Z","url":"https://x.com/ChatGPT/status/2118168231617700199"},{"id":"x62bu2fgvqqixlotmawy3zmxv","title":"OpenAI 发布 GPT Image 2.6 Sunburst 与 Flare，速度提升近 2 倍","summary":"Arena 宣布 OpenAI 的 GPT Image 2.6 Sunburst 和 Flare 上线，据称比 GPT Image 2.5 快 2 倍以上，最低延迟可达 5 秒。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-05T00:31:20.000Z","url":"https://x.com/arena/status/2118139063345787124"},{"id":"umgmuegnck66u7urzxbiruhum","title":"Higgsfield AI 推出 GPT-Image-2.6 限免活动","summary":"优惠详情：\n\n> GPT-Image-2.6 Flare 和 Sunburst 无限使用 7 天\n> 面向 Pro、Plus、Max 和 Ultra 套餐的新用户","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-05T00:11:43.000Z","url":"https://x.com/higgsfield/status/2118134127086215499"},{"id":"lcdap1o18bh6bt70ij66nakij","title":"Higgsfield 上线 GPT Image 2.6，新用户 7 天无限使用","summary":"Higgsfield 宣布 GPT Image 2.6 已上线，新用户可 7 天无限使用。功能包括把提示词或图片转成 GIF、保存参考图随时复用、通过 markup 细化并导出 SVG。OpenAI 此前介绍 ChatGPT Images 2.6 新增 GIF 和参考图功能，另有两款 API 模型将带来 50% 更快的图像生成。","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-05T00:11:42.000Z","url":"https://x.com/higgsfield/status/2118134123533623424"},{"id":"hgl8n52jtawmq03wmiy5ksgf4","title":"fal 上线 OpenAI gpt-image-2.6 的 Sunburst 与 Flare 图像模型","summary":"fal 上线 OpenAI gpt-image-2.6 的四个模型入口，包括 Sunburst Text-to-Image、Sunburst Edit、Flare Text-to-Image 和 Flare Edit，并给出 fal.ai 上的试用链接。","sourceName":"X：fal (@fal)","firstParty":false,"publishedAt":"2026-11-04T23:46:53.000Z","url":"https://x.com/fal/status/2118127876843205032"},{"id":"ckoor7mjziavjeua4n36wjaxc","title":"fal 上线 GPT Image 2.6","summary":"fal 宣布 GPT Image 2.6 已可在其平台使用。新能力包括在图片上画圈、箭头和标注来引导编辑，文本生成图像和编辑均支持输出动画 GIF，并提供从 low 到 max 共五档推理强度。","sourceName":"X：fal (@fal)","firstParty":false,"publishedAt":"2026-11-04T23:46:52.000Z","url":"https://x.com/fal/status/2118127874926407952"},{"id":"w5zdd70hao0x58ifak6pgf9pz","title":"OpenAI 推出 Images 2.6 模型，ChatGPT 支持直接生成和编辑 GIF 动画","summary":"OpenAI 随新 Images 2.6 模型为 ChatGPT 推出 GIF 生成功能，用户可通过提示词或上传照片创建 GIF，并调整动画速度、编辑单个帧和分享。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-04T23:41:17.163Z","url":"https://www.ithome.com/1/022/486.htm"},{"id":"o915zd1u1eq13gyo9x3nsgoq8","title":"OpenAI 发布 Images 2.6 并向所有档位开放 Codex","summary":"OpenAI 宣布 Images 2.6 今日起在 ChatGPT 中可用，Codex 同时面向所有档位开放，覆盖 web、桌面和移动端。GPT-Image-2.6 Flare 和 Sunburst 也已在 API 中提供，详情见官方页面 https://openai.com/index/introducing-images-2-6/。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:35:19.000Z","url":"https://x.com/OpenAI/status/2118124966055223755"},{"id":"v4926jbeulchfze584bf3em1r","title":"OpenAI 发布 GPT-Image-2.6 Flare 与 Sunburst 两款开发者图像模型","summary":"OpenAI 发布面向开发者的两款新图像模型 GPT-Image-2.6 Flare 和 Sunburst。Flare 最快六秒即可生成图像；Sunburst 主打更高质量的生成和跨编辑的一致性。两者还支持图像标记与 SVG 导出，便于进一步精修和使用生成结果。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:35:18.000Z","url":"https://x.com/OpenAI/status/2118124964197114039"},{"id":"lgg076xbmrpmfpdoi1xa50pf0","title":"ChatGPT Images 2.6 支持生成动图 GIF","summary":"GIF 动图！\n\n用 ChatGPT Images 2.6，把提示词或图片变成动态 GIF。\n\n可调整速度、编辑单帧，还能循环分享。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:35:16.000Z","url":"https://x.com/OpenAI/status/2118124953832935810"},{"id":"jkz26nto61yp9panc1o0bj38s","title":"OpenAI 发布 ChatGPT Images 2.6，新增 GIF 与参考图功能","summary":"OpenAI 发布 ChatGPT Images 2.6，新增 GIF 和参考图功能。同时宣布两款新模型即将登陆 API，图像生成速度提升 50%。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:35:14.000Z","url":"https://x.com/OpenAI/status/2118124944928432327"},{"id":"fgh2jnkm6pmhmgzuj6027pu43","title":"OpenAI 教你用静态角色制作循环 GIF","summary":"把静态角色、精灵图或吉祥物做成循环 GIF，用于视频、游戏或应用。\n\n从美术素材开始，描述你想要的动效。试试挥手、回头或胜利舞，并让动作循环回起始姿势。","sourceName":"X：OpenAI Developers (@OpenAIDevs)","firstParty":false,"publishedAt":"2026-11-04T23:34:29.000Z","url":"https://x.com/OpenAIDevs/status/2118124755442151684"},{"id":"pgdl5xjrrav478d5ctidbvt7i","title":"OpenAI 介绍 GPT Image 2.6 Flare 低画质下最快六秒生成图像","summary":"OpenAI 介绍 GPT Image 2.6 Flare 在画质设为 low 时最快六秒即可生成一张图像。引用 @DesignArena 数据称，GPT Image 2.6 Sunburst 在 Image Arena 排名第一，超过前代 2.5 Sunburst，其中 2.6 Flare 比前代快 2.6 倍，2.6 Sunburst 快 1.15 倍。","sourceName":"X：OpenAI Developers (@OpenAIDevs)","firstParty":false,"publishedAt":"2026-11-04T23:34:29.000Z","url":"https://x.com/OpenAIDevs/status/2118124757639966858"},{"id":"j7mpmw4fk1ud0u49x0gjzubyo","title":"OpenAI 将 GPT-Image-2.6 引入 Codex 和 API","summary":"OpenAI 将 GPT-Image-2.6 引入 Codex 和 API。新 API 图像模型 Flare 和 Sunburst 生成速度比之前快 50%；在 medium 或 high 质量下，Sunburst 能在多次编辑间保持细节更一致。","sourceName":"X：OpenAI Developers (@OpenAIDevs)","firstParty":false,"publishedAt":"2026-11-04T23:34:28.000Z","url":"https://x.com/OpenAIDevs/status/2118124753340756055"},{"id":"xe7e23trxt0hyvsvlq5rtrmui","title":"OpenAI 发布 Images 2.6，ChatGPT 支持文本和照片生成动画 GIF","summary":"OpenAI 基于新模型 Images 2.6 在 ChatGPT 中上线 GIF 生成功能，正向网页、桌面和移动端所有 ChatGPT 和 Codex 用户推送。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-04T19:44:20.000Z","url":"https://the-decoder.com/chatgpt-can-now-turn-text-prompts-and-photos-into-animated-gifs-with-openais-images-2-6-model/"},{"id":"zsx5ofvv8iyuit5ytfvqvfllu","title":"OpenAI 为 ChatGPT 上线 GIF 生成并发布 Images 2.6 模型","summary":"OpenAI 随 Images 2.6 模型为 ChatGPT 上线 GIF 生成，可单步生成动图并调整播放速度、逐帧编辑和分享，此前 ChatGPT 无法一步原生生成 GIF。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-04T18:00:00.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1026474/openai-chatgpt-animated-gifs-images-2-6"},{"id":"hoc5e7f6m140ydnyhciavbgwj","title":"OpenAI 发布 GPT-Image-2.6（Sunburst 与 Flare）系统卡","summary":"OpenAI 发布 ChatGPT Images 2.6 系统卡，涵盖 GPT-Image-2.6 Sunburst 与 GPT-Image-2.6 Flare 的训练数据、安全评估与防护措施。","sourceName":"OpenAI：部署安全与系统卡（网页）","firstParty":true,"publishedAt":"2026-11-04T07:00:00.000Z","url":"https://deploymentsafety.openai.com/chatgpt-images-2-6"},{"id":"wwltahauj3uhzwy9yizi2i6f3","title":"OpenAI 发布 Images 2.6，生成提速 50% 并新增 GIF 动画能力","summary":"OpenAI 在 ChatGPT、Codex 和 API 中推出 Images 2.6，图像生成速度比之前快 50%，并支持用 GIF 为图像添加动画。API 提供 GPT-Image-2.6 Flare（低质量下最快 6 秒出图）和 GPT-Image-2.6 Sunburst（中高质量下更精细）两个模型。","sourceName":"OpenAI：官网动态（RSS · 排除企业/客户案例）","firstParty":true,"publishedAt":"2026-11-04T00:00:00.000Z","url":"https://openai.com/index/introducing-images-2-6"}]},"0b20bea7-a1d4-451e-bb1b-38c63fadf89f":{"publicId":"0b20bea7-a1d4-451e-bb1b-38c63fadf89f","title":"Claude Code 产品负责人 Cat Wu 转投 OpenAI","status":"active","sourceCount":4,"reportCount":4,"firstReportAt":"2026-11-05T00:25:34.000Z","latestAt":"2026-11-05T12:20:35.000Z","latest":"Claude Code 产品负责人 Catherine Wu 跳槽 OpenAI 主管 Core Products 产品","digest":"Anthropic Claude Code 产品负责人 Cat Wu 在 X 上宣布加入 OpenAI，领导 Core Products 的产品管理。她称将与 @thsottiaux 及 OpenAI 产品团队合作打造智能体产品，强调让用户保持掌控、节省时间，并表示敬佩 OpenAI 证明 scaling 有效、将 AI 带给超十亿人。\n\nOpenAI 联合创始人 Greg Brockman 与 @thsottiaux 先后转发并欢迎她加入，确认了这一人事变动。The Decoder 报道称，负责 Codex 和 ChatGPT 的 Thibault Sottiaux 以“CatGPT”迎接她。OpenAI 方面尚未就她的具体职责范围作进一步说明。","digestUpdatedAt":"2026-11-05T13:01:21.785Z","reports":[{"id":"fexoyemkfcd2534uy2823qx0i","title":"Claude Code 产品负责人 Catherine Wu 跳槽 OpenAI 主管 Core Products 产品","summary":"Claude Code 产品负责人 Catherine Wu 宣布加入 OpenAI，领导 Core Products 的产品管理，Codex 和 ChatGPT 负责人 Thibault Sottiaux 以 \"CatGPT\" 迎接她。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-05T12:20:35.000Z","url":"https://the-decoder.com/anthropic-loses-product-lead-catherine-wu-behind-claude-code-to-openai/"},{"id":"jsdt72s1n09hnlezc2uqqg1da","title":"Cat Wu 宣布加入 OpenAI 担任核心产品负责人","summary":"_catwu 宣布加入 OpenAI，负责 Core Products 的产品管理。她表示期待与 @thsottiaux 及 OpenAI 团队一起打造可信赖的智能体产品，并请用户继续反馈。作者 Tibo 转发并对其表示欢迎。","sourceName":"X：Tibo (@thsottiaux)","firstParty":true,"publishedAt":"2026-11-05T00:29:41.000Z","url":"https://x.com/thsottiaux/status/2118138648214585591"},{"id":"qvj3vkf6aagjfet1txpmwfzu6","title":"OpenAI 迎来 Cat Wu 负责核心产品","summary":"欢迎 @_catwu 加入团队！！","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-05T00:28:23.000Z","url":"https://x.com/gdb/status/2118138320375136695"},{"id":"vuczr7bm6ge6s1vnezna4ifxn","title":"Anthropic Claude Code 产品负责人 Cat Wu 跳槽 OpenAI","summary":"Anthropic Claude Code 产品负责人 Cat Wu 宣布加入 OpenAI，负责 Core Products 的产品管理。她表示将与 @thsottiaux 及 OpenAI 产品团队合作打造智能体产品，强调让用户保持掌控、节省时间。她称敬佩 OpenAI 证明 scaling 有效、将 AI 带给超十亿人。","sourceName":"X：Cat Wu（Anthropic，Claude Code 产品负责人） (@_catwu)","firstParty":false,"publishedAt":"2026-11-05T00:25:34.000Z","url":"https://x.com/_catwu/status/2118137612577968402"}]},"491d220c-9d57-4295-af9f-e4382561b3f7":{"publicId":"491d220c-9d57-4295-af9f-e4382561b3f7","title":"腾讯混元 Hy4 正式发布，首增视觉与电脑操作","status":"active","sourceCount":10,"reportCount":16,"firstReportAt":"2026-10-29T02:18:32.043Z","latestAt":"2026-11-05T18:55:35.000Z","latest":"WorkBuddy 限时免费开放 Hy4","digest":"腾讯混元 11 月 4 日发布 Hy4 正式版，相比 8 月 28 日的 Hy4 preview 扩大预训练与后训练规模，首次引入视觉能力和电脑操作支持，可执行细粒度图像处理、复杂图表分析、数学视觉推理，以及结合命令行与图形界面的任务。腾讯混元称，Hy4 在 GameDev 与 GameLogic 评测上分别提升 19.1% 和 9.8%，性能显著超过 preview，同时维持相同 API 价格；The Decoder 报道其每百万输入 token 约 0.83 美元、输出约 2.50 美元。腾讯混元还称其首次跻身最强开源模型之列，计划近期开源模型权重并发布模型系统卡片，但权重开放日期未定，目前仅通过腾讯云、OpenRouter 和元宝等腾讯应用使用。上述提升与开源计划均来自腾讯方面，实际效果尚待验证。\n\nHy4 已在腾讯云和 OpenRouter 上线，并可在 CodeBuddy / WorkBuddy、元宝、ima 等产品上体验；WorkBuddy 称 Hy4 可免费试用，但有使用额度限制，随后又称限时免费开放。腾讯混元称，Hy4 在 WorkBuddy 上线首日有大量用户触及额度，已对推理集群紧急扩容十倍并提升免费体验额度，Hy3 的 WorkBuddy 限免延长至 11 月 15 日 23:59。OpenClaw 随后宣布支持 Hy4，用户可通过 Tencent TokenHub、TokenPlan 和 OpenRouter 使用；腾讯混元另称 Hy4 即将上线 Chutes，并已上架 Vercel AI Gateway，2026 年 12 月 31 日前五折。\n\nArena 公布 Hy4 在 Agent Arena 总榜排名第 14，基于 8.5K+ 真实长程智能体会话，净提升 +4.7%，进入 Pareto 前沿；Arena 称其目前为专有模型，权重开放后将与 Kimi K3.1 Pro 并列开源模型第一，得分相差不到 1 个百分点，价格 $0.55/task 比后者 $1.46/task 低约 62%。此前 Arena 引用数据显示，Hy4 preview 上月以开源模型身份位列 Agent Arena 第 2（总榜第 10），成本约 $0.26 per median task。","digestUpdatedAt":"2026-11-05T23:10:03.750Z","reports":[{"id":"mq4bqroegt576ybug0iw5tr0s","title":"WorkBuddy 限时免费开放 Hy4","summary":"Hy4。免费。在 WorkBuddy 里。\n限时开放，所以……别错过。","sourceName":"X：Tencent WorkBuddy (@WorkBuddy_AI)","firstParty":false,"publishedAt":"2026-11-05T18:55:35.000Z","url":"https://x.com/WorkBuddy_AI/status/2118416957502591114"},{"id":"rifbsuwh2qe2ffsoeck0z1ces","title":"腾讯发布 Hy4：首次支持图像理解与计算机操作，权重后续开放","summary":"腾讯在预览约两个月后正式发布大语言模型 Hy4，首次支持图像理解和自主操作软件，权重将在未定日期开放，目前可通过 Tencent Cloud、OpenRouter 和元宝使用。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-05T16:06:31.000Z","url":"https://the-decoder.com/tencent-releases-hy4-with-vision-and-computer-use-claims-second-place-among-chinese-ai-models/"},{"id":"jk5498zofdt9yf2pa6ri70x6u","title":"腾讯混元：Hy4 在 WorkBuddy 调用激增，推理集群紧急扩容十倍、Hy3 限免延长","summary":"腾讯混元 Hy4 自 2026 年 11 月 4 日在 WorkBuddy 首发接入后，上线首日任务队列中出现大量用户触及额度，官方已对 Hy4 推理集群紧急扩容十倍并提升免费体验额度。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-05T10:04:57.680Z","url":"https://www.ithome.com/1/022/922.htm"},{"id":"k75mgnyadez7s3zfdv00z85yv","title":"腾讯混元Hy4上线Vercel AI Gateway","summary":"+ Vercel 🤝","sourceName":"X：腾讯混元 (@TencentHunyuan)","firstParty":false,"publishedAt":"2026-11-05T09:45:20.000Z","url":"https://x.com/TencentHunyuan/status/2118278484124721580"},{"id":"cbdgw8lsvan2m0wl5wddax4om","title":"腾讯发布 Hy4 模型，称其跻身中国顶尖模型之列并计划开源权重","summary":"腾讯发布新模型 Hy4，据 Bloomberg 报道称其跻身中国顶尖模型之列，并计划很快开源模型权重。模型由 Hy4-Preview 扩大而来，具备原生视觉能力和 Deep Research，在独立行情图表类基准中表现超过 DeepSeek 和智谱 AI。引用推文还称其可以交易 A 股，但提示用户需自行谨慎判断。","sourceName":"X：X.PIN (@thexpin)","firstParty":false,"publishedAt":"2026-11-05T07:55:27.000Z","url":"https://x.com/thexpin/status/2118250829195120743"},{"id":"obzx6c2f12228rusl9kms4me0","title":"腾讯混元 Hy4 现已支持在 OpenClaw 中使用","summary":"腾讯混元宣布 Hy4 现已支持在 OpenClaw 中使用。引用内容提到 Hy4 具备视觉能力、1M-token 上下文窗口，并改进了编码和长程智能体能力，可通过 Tencent TokenHub、TokenPlan 和 OpenRouter 获取，详情见 https://hy.tencent.ai/research/hy4 。","sourceName":"X：腾讯混元 (@TencentHunyuan)","firstParty":false,"publishedAt":"2026-11-05T02:34:21.000Z","url":"https://x.com/TencentHunyuan/status/2118170021856006185"},{"id":"njt8r5kuxihgbz09743ocymzq","title":"腾讯混元Hy4即将上线Chutes","summary":"Hy4 即将登陆 Chutes 🥳","sourceName":"X：腾讯混元 (@TencentHunyuan)","firstParty":false,"publishedAt":"2026-11-05T02:31:27.000Z","url":"https://x.com/TencentHunyuan/status/2118169289996009784"},{"id":"qh3yf0i9zuqo0m7sgo601taho","title":"Latent Space 幕后访谈：Kill My SaaS、Jev 与 2026 年 AI 展望及 AI Engineer 上海站","summary":"Latent Space 发布幕后访谈，聊 Kill My SaaS、Jev 与 2026 年 AI 趋势，并收录 AI Engineer 上海站内容。本期 AI News 覆盖 11/02-11/03 动态：腾讯 Hy4 在 APEX-Agents 得 75.2，API 定价 $0.834/$2.501 每百万 token 并计划开源权重；Kimi K3.1 Pro 权重定于周三发布。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-04T19:17:30.000Z","url":"https://latent.space/p/ainews-behind-latent-space-kill-my-saas-jev-ai-in-2026-aiei-shanghai/"},{"id":"o9ls8b5otqv36vynok884y2ay","title":"OpenClaw 支持腾讯混元 Hy4 模型","summary":"OpenClaw 宣布支持腾讯混元 Hy4，模型具备视觉能力、1M-token 上下文窗口以及改进的编码和长程智能体能力。用户可通过 Tencent TokenHub、TokenPlan 和 OpenRouter 使用，详情见 https://hy.tencent.ai/research/hy4。","sourceName":"X：OpenClaw (@openclaw)","firstParty":false,"publishedAt":"2026-11-04T17:35:07.000Z","url":"https://x.com/openclaw/status/2118034317024923652"},{"id":"sskf8g1aaa7os7ev40rnhk12p","title":"腾讯发布开源大模型 Hy4","summary":"腾讯发布最新一代大语言模型 Hy4，称其已进入全球领先开源模型行列，权重和系统卡将在未来几天放出。模型首次引入视觉理解和 computer-use 能力，可操作命令行和图形界面，并针对 Blender、CAD 等专业软件训练。","sourceName":"Hacker News：AI 热帖","firstParty":false,"publishedAt":"2026-11-04T08:06:53.000Z","url":"https://www.tencent.com/tencent-launches-hy4-joining-the-ranks-of-the-worlds-leading-open-source-ai-models/"},{"id":"w8wo5grevjwdhfetomcgyp19c","title":"混元 Hy4 登上 Agent Arena 总榜第14名","summary":"Arena 宣布腾讯混元 Hy4 在 Agent Arena 总榜排名第14，基于全球用户 8.5K+ 真实长程智能体会话，净提升 +4.7%，进入 Pareto 前沿。目前为专有模型，作者称权重开放后将与 Kimi K3.1 Pro 并列开源模型第一；其得分与 Kimi K3.1 Pro (Max) 相差不到1个百分点，价格 $0.55/task 比 $1.46/task 低约62%。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-04T07:15:01.000Z","url":"https://x.com/arena/status/2117878267504103555"},{"id":"s6mo1gds5y5qwtzoehdx8isdr","title":"Hy4 开源模型上线 WorkBuddy","summary":"Hy4，最强开源权重模型之一，现已登陆 WorkBuddy。\n犀利、快速，用起来真的很有趣。\n选它。试它。随时切换。\n免费试用，有使用额度限制。","sourceName":"X：Tencent WorkBuddy (@WorkBuddy_AI)","firstParty":false,"publishedAt":"2026-11-04T06:10:15.000Z","url":"https://x.com/WorkBuddy_AI/status/2117861966421324162"},{"id":"l2rqbuukynxny9026apag2cpd","title":"腾讯混元 Hy4 正式版发布，称首次跻身最强开源模型之列","summary":"腾讯混元 11 月 4 日发布大语言模型 Hy4 正式版，官方称 Hy 首次跻身最强开源模型之列，计划近期开源模型权重并发布模型系统卡片。相比 Hy4 preview，该模型扩展了预训练和后训练规模，首次引入视觉能力和电脑操作支持，可执行细粒度图像处理、复杂图表分析、数学视觉推理及结合命令行与图形界面的任务。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-04T04:59:42.330Z","url":"https://www.ithome.com/1/022/035.htm"},{"id":"z6j7q1gcuwsjjpx3qbtnvl2b3","title":"腾讯混元 Hy4 正式发布，首次引入视觉与电脑操作能力","summary":"腾讯混元发布 Hy4 正式版，相比 Hy4 preview 扩展预训练与后训练规模，首次引入视觉能力和电脑操作支持，GameDev 与 GameLogic 评测分别提升 19.1% 和 9.8%。","sourceName":"公众号：腾讯混元","firstParty":false,"publishedAt":"2026-11-04T04:43:55.000Z","url":"https://mp.weixin.qq.com/s/JrQeiqx3PXBDSGish2IzwA"},{"id":"tdqw8omc0eao2xnhv3wojyipt","title":"Arena 预告腾讯混元 Hy4 即将上线并回顾 Hy4 preview 表现","summary":"Arena 预告腾讯混元 Hy4 即将推出，届时将在 Arena 排行榜上公布其表现。其引用的数据显示，Hy4 preview 上月以开源模型身份位列 Agent Arena 第 2（总榜第 10），在 14.5K+ 真实智能体会话中净提升 +5.4%，仅落后 Kimi K3 (Max) 的 +6.6%；成本约 $0.26 per median task，比 $0.80 低约 68%，已进入 Pareto frontier；Confirmed Success 12%、Bash Recovery 7.5%，无 Tool Hallucination 问题，并在 Code 和 Work 类别中居开源模型第 2。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-03T17:31:33.000Z","url":"https://x.com/arena/status/2117671035491557679"},{"id":"nbbhsgm9vpgyuk3fs9hjz576f","title":"腾讯混元 Hy4、Hy4 flash 即将发布，首次引入视觉理解","summary":"腾讯在腾讯全球数字生态大会上宣布 Hy4 即将发布，相比 Hy4 preview 全面大幅提升，强化长程与真实生产力任务能力，显著提升思维链效率，并首次引入视觉理解。Hy4 flash 也将在近期发布，定位极致性价比的实用模型，继承 Hy4 的视觉、Agent 等能力。此前 8 月 28 日发布的 Hy4 preview 总参数 770B、激活参数 49B、上下文长度 1M。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-29T02:18:32.043Z","url":"https://www.ithome.com/1/019/328.htm"}]},"16df653b-997f-4488-afe7-4f9c0779fc05":{"publicId":"16df653b-997f-4488-afe7-4f9c0779fc05","title":"Anthropic 在美国推出 Claude 个人财务测试版","status":"active","sourceCount":9,"reportCount":10,"firstReportAt":"2026-11-05T00:00:00.000Z","latestAt":"2026-11-06T00:37:10.937Z","latest":"Anthropic 推出 Claude 个人理财功能，支持消费分析和账单追踪","digest":"Anthropic 在 Claude 中上线 Personal Finance 个人财务功能，本周起以测试版形式逐步向美国 Pro、Max 和 Ultra 订阅用户开放。用户通过 Plaid 以只读方式连接自己选择的银行和卡账户，可用日常语言询问与自身余额和交易记录相关的财务问题，也可按类别汇总支出、标记重复扣款和异常费用，并解释 APR 等金融概念。\n\nAnthropic 称，该功能对账户的访问权限为只读，Claude 无法移动、管理或投资用户资金；用户可随时解绑账户。Anthropic 还称，该功能没有广告或赞助推荐，用于帮助用户理解个人财务，并非用于提供投资建议；相关对话不用于模型训练。","digestUpdatedAt":"2026-11-06T01:03:58.936Z","reports":[{"id":"vz7tqyuw4ofxzf1ku553bqenf","title":"Anthropic 推出 Claude 个人理财功能，支持消费分析和账单追踪","summary":"Anthropic 于当地时间 11 月 5 日宣布为 Claude 加入个人理财功能，本周开启灰度测试，面向美国地区 Pro、Max 和 Ultra 订阅用户开放。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-06T00:37:10.937Z","url":"https://www.ithome.com/1/023/051.htm"},{"id":"s2ufq241tm3qx17yu26ekkaj5","title":"Anthropic 推出 Claude Personal Finance 测试版，通过 Plaid 只读连接银行账户","summary":"Anthropic 在美国推出 Claude 的 Personal Finance 测试版，通过 Plaid 以只读方式连接银行账户，Claude 可用日常语言回答用户余额和交易相关问题，但不能移动、管理或投资资金。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-05T21:59:58.000Z","url":"https://x.com/rohanpaul_ai/status/2118463359217799495"},{"id":"n07lda6rfn68gtap5n36k3iaw","title":"Claude 推出个人理财功能，测试版首先在美国开放","summary":"Anthropic 官方宣布在 Claude 中推出个人理财功能（Personal Finance in Claude），测试版目前限美国。用户可自行选择连接的账户，Claude 用日常语言基于自己的余额和交易回答理财问题；访问为只读，Claude 不能转移、管理或投资用户的资金。","sourceName":"X：Ado Kukic（Anthropic 开发者关系，Claude Code） (@adocomplete)","firstParty":false,"publishedAt":"2026-11-05T19:07:34.000Z","url":"https://x.com/adocomplete/status/2118419971806269544"},{"id":"cnpil1rx0rhng6ajatn4i9ylz","title":"Claude 推出个人理财功能","summary":"Claude 个人理财功能现已推出，美国地区 beta 版。\n\n连接你选择的账户，Claude 就能用日常语言回答你的财务问题，基于你自己的余额和交易记录。访问权限为只读，Claude 无法移动、管理或投资你的资金。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-05T18:00:35.000Z","url":"https://x.com/claudeai/status/2118403114890137895"},{"id":"nylr2txlbqndcbir9pgb1srrg","title":"Claude 推出 Personal Finance 功能，逐步在美国 Pro、Max 和 Ultra 计划上线","summary":"Anthropic 为 Claude 推出 Personal Finance 功能，无广告和赞助推荐，用于帮助用户理解个人财务，不用于提供投资建议。该功能正逐步向美国 Pro、Max 和 Ultra 计划用户开放。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-05T18:00:35.000Z","url":"https://x.com/claudeai/status/2118403117779988744"},{"id":"gte01cctvn6tw8c2uzy5xcbsx","title":"Claude 推出个人理财功能 Personal Finance","summary":"Claude 上线个人理财功能 Personal Finance，用户连接账户后，Claude 可解释消费、账单和余额情况。该功能为只读访问，用户可自选账户并随时解绑，目前处于 beta 阶段，正逐步向美国 Pro、Max 和 Ultra 套餐用户开放。","sourceName":"Claude：YouTube（RSS）","firstParty":true,"publishedAt":"2026-11-05T18:00:30.000Z","url":"https://www.youtube.com/watch?v=UTubvRLX2j4"},{"id":"fab8mvwmcoe7dcnrohfdjmcqu","title":"Anthropic 为 Claude 推出 Personal Finance 个人财务工具","summary":"Anthropic 周四宣布为 Claude 推出 Personal Finance 工具，用户可通过 Plaid 连接银行和信用卡账户，向 Claude 询问消费情况。该工具为只读权限，不能动用或投资用户资金，可按类别汇总支出、标记重复扣款和异常费用，并解释 APR 等金融概念；相关对话不用于模型训练。工具本周以 Beta 形式向美国 Pro、Max 和 Ultra 套餐用户推出。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-05T18:00:00.000Z","url":"https://techcrunch.com/2026/11/05/claude-can-now-analyze-your-spending-with-its-new-personal-finance-tool/"},{"id":"vyppmpt6y4fnafymmzp7unyzd","title":"Anthropic 推出 Claude Personal Finance 功能，可经 Plaid 连接银行账户","summary":"Anthropic 推出 Claude 的 Personal Finance 功能，通过 Plaid 连接用户的银行和卡账户，本周以 beta 形式向美国 Claude Pro、Max 和 Ultra 订阅者开放。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-05T18:00:00.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1027652/anthropic-claude-plaid-personal-finance"},{"id":"m70cbaxy1ew2sgmlkernbvi68","title":"Claude 推出 Personal Finance 个人理财功能，Pro、Max、Ultra 美国用户本周起 Beta 试用","summary":"Anthropic 在 Claude 中推出 Personal Finance 个人理财功能，本周起向美国 Pro、Max、Ultra 计划用户开放 Beta。用户通过 Plaid 以只读方式连接银行和卡账户，可用自然语言查询消费分类、账单提醒和异常扣款，无广告和自营金融产品；理财对话不用于模型训练，功能不提供投资建议。","sourceName":"Claude：Blog（网页）","firstParty":true,"publishedAt":"2026-11-05T00:00:00.000Z","url":"https://claude.com/blog/introducing-personal-finance-in-claude"},{"id":"v3s2fd3kdvqi0lkmsqe707clp","title":"Claude Enterprise 新增安全与管理控制，Claude 推出 Personal Finance 测试版","summary":"Claude Enterprise 新增安全中心、推理钩子（inference hooks）、集中管理和更多访问控制功能，其中多项处于测试阶段。Claude 同时向 Pro、Max 和 Ultra 套餐推出 Personal Finance 测试版，可关联银行、信用卡、贷款和投资账户，在一个页面查看余额与支出并向 Claude 提问，目前仅限美国。","sourceName":"Claude 应用发布说明","firstParty":true,"publishedAt":"2026-11-05T00:00:00.000Z","url":"https://support.claude.com/en/articles/12138966-release-notes#h_1c75a86390"}]},"d6acd01b-e9cc-4a1f-9732-6f49b5859ee5":{"publicId":"d6acd01b-e9cc-4a1f-9732-6f49b5859ee5","title":"Thinking Machines 发布 Inkling 2 Small，先闭源上线 Tinker","status":"active","sourceCount":8,"reportCount":10,"firstReportAt":"2026-11-04T16:00:00.000Z","latestAt":"2026-11-06T04:25:07.000Z","latest":"Thinking Machines 发布 Inkling 2 Small：594B MoE、17B 激活、1M 上下文","digest":"Thinking Machines Lab 发布第二代模型 Inkling 2 Small，即日起在 Tinker 平台提供微调和推理，初期为闭源权重。公司称，完整权重计划于下周以 Apache 2.0 许可开放，前提是完成外部安全测试和红队评估。\n\n该模型为 594B 总参数、17B 激活的 MoE，支持图像输入和 1M token 上下文。Artificial Analysis 称其在 Intelligence Index v5.0.1 上得 31 分，较前代提升 18 分；若权重按计划开源，按当前排名将成为中国以外得分最高的开源权重模型。Tinker 定价为每百万输入/输出 token 0.30 美元和 1.00 美元，缓存输入每百万 token 0.03 美元。Arena 称其在 Code Arena: WebDev 的 AutoEval 得 1654 分，约列总榜第 20、美国开源模型第一。\n\n公司还称其擅长长周期任务、能以视觉方式检查自身工作，用户可自行微调或让模型自主编排微调流程。公司员工 Karina Nguyen 分享的案例称，该模型智能体在财务尽调任务中自行下载并解析 PSEG 10-Q，发现需从经营现金流中剔除的 12 亿美元抵押品释放，得分 0.82，高于次优模型的 0.67。上述能力与得分均为公司或相关机构说法，尚未见独立验证。","digestUpdatedAt":"2026-11-06T06:54:10.098Z","reports":[{"id":"eil7g827qnurbw83ytbjpokhb","title":"Thinking Machines 发布 Inkling 2 Small：594B MoE、17B 激活、1M 上下文","summary":"Thinking Machines Lab 发布第二代 Inkling 首款模型 Inkling 2 Small，为 594B 总参数、17B 激活的稀疏 MoE，支持文本与图像输入、1M token 上下文和可变推理强度。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-06T04:25:07.000Z","url":"https://www.marktechpost.com/2026/11/05/thinking-machines-inkling-2-small-release/"},{"id":"exer6wv2kt3nbwubog2yrjgh0","title":"Inkling 2 Small 自主改进模型能力","summary":"应用了 RSI 🚀","sourceName":"X：Karina Nguyen（@karinanguyen）","firstParty":false,"publishedAt":"2026-11-06T00:01:47.000Z","url":"https://x.com/karinanguyen/status/2118494016165777441"},{"id":"xpmyon7tezenro4k4fmlbf3th","title":"Thinking Machines 发布 Inkling 2 Small，Artificial Analysis 指数得分 31 并计划开源权重","summary":"Thinking Machines 发布 Inkling 2 Small，在 Artificial Analysis Intelligence Index v5.0.1 得分 31，较 Inkling Small 提升 18 分，计划以 Apache 2.0 发布权重，若落实将成为中国以外得分最高的开源权重模型。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-05T23:59:15.000Z","url":"https://x.com/ArtificialAnlys/status/2118493376186388530"},{"id":"c66xa3anti4ibc6om7fcq1owk","title":"Inkling 2 Small 进入 Code Arena: WebDev 榜单，1654 分约列美国开源模型第一","summary":"Arena 宣布 Thinking Machines 的 Inkling 2 Small 进入 Code Arena: WebDev，AutoEval 得 1654 分，约列总榜第 20、美国开源模型第一。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-05T23:55:05.000Z","url":"https://x.com/arena/status/2118492327887155680"},{"id":"dfl6x1foulmm0456amukc5na6","title":"Karina Nguyen 演示 Inkling 2 Small 在财务尽调任务中独立解析 PSEG 10-Q 并发现 12 亿美元抵押品释放","summary":"Karina Nguyen 分享一个 Inkling 2 Small 智能体的实测轨迹：当申报工具只返回 PSEG 的目录时，该智能体自行下载完整的 3.7MB 10-Q，用 Python 解析，并发现需从经营现金流中剔除的 12 亿美元抵押品释放，得分 0.82，高于次优模型的 0.67。引用的 @thoughtfullab 内容称其在 DiligenceBench 上表现良好，该模型为 594B 参数、17B 激活参数的 MoE，定价 $0.30/M 输入和 $1/M 输出 token。","sourceName":"X：Karina Nguyen（@karinanguyen）","firstParty":false,"publishedAt":"2026-11-05T23:53:36.000Z","url":"https://x.com/karinanguyen/status/2118491955239989515"},{"id":"o3kzzqpf35qwhqm7w9xvr1xuw","title":"Thinking Machines 发布 Inkling 2 Small 并上线 Tinker","summary":"Mira Murati 宣布 Inkling 2 Small 即日起可在 Tinker 上进行微调和推理，完整权重即将开放。据引用的 Thinking Machines 官方内容，该模型在 AA Intelligence Index 上得 31 分，较前代大幅提升。","sourceName":"X：Mira Murati（@miramurati）","firstParty":false,"publishedAt":"2026-11-05T23:45:03.000Z","url":"https://x.com/miramurati/status/2118489804585509192"},{"id":"hca5pexdy88fstdlafrqet4iq","title":"Thinking Machines 发布 Inkling 2 Small","summary":"推出 Inkling 2 Small。在 AA Intelligence Index 上得分 31，相较前代大幅提升。\n\nInkling 2 Small 即日起可在 Tinker 上进行微调和推理，完整权重发布计划于近期推出。\n\nhttps://thinkingmachines.ai/news/inkling-2-small","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-05T23:43:57.000Z","url":"https://x.com/thinkymachines/status/2118489527362912566"},{"id":"j2wy2avc7gqke53hk08kztvy1","title":"Thinking Machines 介绍 Inkling 2 Small 的长任务与视觉自检能力，开放 Tinker 微调","summary":"Thinking Machines 介绍 Inkling 2 Small，称其擅长长周期任务、能以视觉方式检查自身工作，并可适配不同的 harness 和环境。用户可在 Tinker 上对其微调，或让 Inkling 2 Small 自主编排微调流程。","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-05T23:43:57.000Z","url":"https://x.com/thinkymachines/status/2118489528424104201"},{"id":"bu8612ca3e1uyxjppk56ef1wl","title":"Thinking Machines Lab 发布 Inkling 2 Small：594B 参数 MoE 模型，下周开放 Apache 2.0 权重","summary":"Thinking Machines Lab 发布第二代模型 Inkling 2 Small，为 594B 总参数、17B 激活的 MoE 模型，支持图像输入与 variable effort，Artificial Analysis Intelligence Index 得分 31。","sourceName":"Thinking Machines Lab：News（网页）","firstParty":true,"publishedAt":"2026-11-05T07:00:00.000Z","url":"https://thinkingmachines.ai/news/inkling-2-small/"},{"id":"aox2so3ad2v3skhpll59u9fxx","title":"Thinking Machines 发布 Inkling 2 Small，权重将开源为评分最高的中国以外开放权重模型","summary":"Thinking Machines 发布 Inkling 2 Small，在 Artificial Analysis Intelligence Index 得分 31，较 Inkling Small 提升 18 分；计划后续以 Apache 2.0 开放权重，若兑现将是中国以外评分最高的开放权重模型。","sourceName":"Artificial Analysis 完整文章（网页）","firstParty":true,"publishedAt":"2026-11-04T16:00:00.000Z","url":"https://artificialanalysis.ai/articles/thinking-machines-releases-inkling-2-small-highest-scoring-open-weights-model-outside-of-chinia-upon-weights-release-it"}]},"0c969c38-7969-4bd9-9c91-f3cdf9b4a9cd":{"publicId":"0c969c38-7969-4bd9-9c91-f3cdf9b4a9cd","title":"百度开源 280B 参数 ERNIE 5.5 Flash Base 基座模型","status":"active","sourceCount":5,"reportCount":8,"firstReportAt":"2026-11-04T16:00:00.000Z","latestAt":"2026-11-06T02:49:21.000Z","latest":"百度开源 280B 参数的 ERNIE 5.5 Flash Base 基础模型","digest":"百度文心发布并开源基座模型 ERNIE-5.5-Flash-Base，开放预训练终点的权重，在 Hugging Face 提供 FP8 与 BF16 两种 safetensors 下载，采用 ERNIE 5.5 Flash Base Model License Agreement v1.0。百度称该模型为稀疏 MoE 基座语言模型，总参数 280B、每 token 激活 14B，预训练使用 33.5T tokens；权重未经中训练与后训练，供开发者做领域适配、指令微调和强化学习研究，后续将推出后训练版本。\n\n上下文长度上，百度称训练上下文达 128K，微调和推理设计上支持最长 1M-token。MarkTechPost 称其许可在年收入低于 5000 万美元时免费，但排除欧盟、英国和韩国。百度称该模型在同规模基座模型的多个基准上取得 SOTA，报道未给出独立验证。","digestUpdatedAt":"2026-11-06T04:15:31.054Z","reports":[{"id":"yspksmmwaaupllhpgbxcv124h","title":"百度开源 280B 参数的 ERNIE 5.5 Flash Base 基础模型","summary":"百度发布开源基础模型 ERNIE 5.5 Flash Base，参数规模为 280B。该推文附上 the-decoder.com 的报道链接，未给出更多技术细节。","sourceName":"X：百度 Baidu (@Baidu_Inc)","firstParty":false,"publishedAt":"2026-11-06T02:49:21.000Z","url":"https://x.com/Baidu_Inc/status/2118536183663956194"},{"id":"uug280uzx0av4eec817jo9zru","title":"百度发布 ERNIE 5.5 Flash Base：280B 总参、14B 激活的 MoE 基座模型","summary":"百度发布 ERNIE 5.5 Flash Base，这是 280B 总参数、每 token 激活 14B 的稀疏 MoE 基座模型，权重止于预训练阶段，已在 Hugging Face 和 ModelScope 提供 FP8 与 BF16 权重。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-05T21:33:00.000Z","url":"https://www.marktechpost.com/2026/11/05/baidu-ernie-5-5-flash-base-280b-moe/"},{"id":"u0qd4l08l8jg213obn60phr42","title":"百度开源 ERNIE 5.5 Flash Base 基座模型，280B 参数 MoE 架构","summary":"百度发布开源基座模型 ERNIE-5.5-Flash-Base，刻意不带微调或后训练，交由开发者自行处理，后续将推出后训练版本。模型采用 MoE 架构，总参数 280B、每输入激活 14B，预训练数据 33.5 万亿 token，训练上下文最长 128,000 token，微调和推理设计上支持到 100 万 token。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-05T17:56:41.000Z","url":"https://the-decoder.com/baidu-releases-ernie-5-5-flash-base-with-280-billion-parameters-as-an-open-source-foundation-model/"},{"id":"r33a25ocq841v6voh3ypee22r","title":"百度发布 ERNIE 5.5 Flash Base 并上架 Hugging Face","summary":"百度发布 ERNIE 5.5 Flash Base 模型，提供官方博客介绍页 https://ernie.baidu.com/release/ernie-5-5-flash-base/ 和 Hugging Face 下载入口 https://huggingface.co/baidu/ERNIE-5.5-Flash-Base。","sourceName":"X：百度 Baidu (@Baidu_Inc)","firstParty":false,"publishedAt":"2026-11-05T08:55:26.000Z","url":"https://x.com/Baidu_Inc/status/2118265926290419742"},{"id":"p6g76vm44wq8k5yw8oggf1sys","title":"百度开源 ERNIE 5.5 Flash Base 基座模型：280B 总参数、14B 激活","summary":"百度发布 ERNIE 5.5 Flash Base 稀疏 MoE 基座语言模型并开放权重。模型总参数 280B、每 token 激活 14B，预训练 33.5T tokens，微调和推理上下文最长 1M-token，提供 FP8 与 BF16 权重。官方称其在同规模基座模型中于多个基准取得 SOTA，权重直接来自预训练、未做中后期训练，方便研究者在同一 checkpoint 上比较不同方法的效果。","sourceName":"X：百度 Baidu (@Baidu_Inc)","firstParty":false,"publishedAt":"2026-11-05T08:55:25.000Z","url":"https://x.com/Baidu_Inc/status/2118265920665587935"},{"id":"bq5cyj48c8sy4kyvty60vigch","title":"百度文心开源 ERNIE-5.5-Flash-Base 基座模型，总参数 280B 每 token 激活 14B","summary":"百度文心发布开源基座模型 ERNIE-5.5-Flash-Base，开放 ERNIE 5.5 Flash 预训练终点权重。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-05T08:21:01.923Z","url":"https://www.ithome.com/1/022/785.htm"},{"id":"gxgg5gpnpv858z8ab6bqf0ijz","title":"百度开源 ERNIE-5.5-Flash-Base 基座模型","summary":"百度发布 ERNIE-5.5-Flash-Base 基座模型权重，为 280B 总参数、每 token 激活 14B 的稀疏 MoE 模型，从头在 33.5T tokens 上预训练，训练上下文达 128K，微调和推理支持 1M-token 上下文。","sourceName":"百度文心 ERNIE 官方博客","firstParty":true,"publishedAt":"2026-11-04T16:00:00.000Z","url":"https://ernie.baidu.com/release/ernie-5-5-flash-base/"},{"id":"r3360gkpmqpyyt2ii9cp1k9rz","title":"百度发布 ERNIE-5.5-Flash-Base 开源 Base 模型，280B 总参数每 token 激活 14B","summary":"百度文心团队发布 ERNIE-5.5-Flash-Base，在 Hugging Face 开放预训练终点 Base 权重，提供 FP8 与 BF16 两种 safetensors。","sourceName":"百度文心 ERNIE 官方博客","firstParty":true,"publishedAt":"2026-11-04T16:00:00.000Z","url":"https://ernie.baidu.com/zh/release/ernie-5-5-flash-base/"}]},"2d1c9f85-c83f-4755-8376-821ee9e72d27":{"publicId":"2d1c9f85-c83f-4755-8376-821ee9e72d27","title":"OpenAI中期选举后推公关攻势并更名数据中心","status":"active","sourceCount":7,"reportCount":10,"firstReportAt":"2026-11-01T20:13:13.000Z","latestAt":"2026-11-06T00:37:56.000Z","latest":"OpenAI 宣布数据中心社区承诺，不再对公职人员使用 NDA","digest":"OpenAI计划在美国中期选举结束后发起公关与游说攻势，届时将其数据中心改称为“AI算力园区”。据Axios报道，此举的背景是数据中心在两党中都成为政治包袱，攻势将在跛脚鸭会期启动，此时民主党很可能拿下众议院。OpenAI首席全球事务官Chris Lehane是这一包装的提出者，他还提到推动设立AI“限速”、让民众感受到AI对日常生活的赋能，并推动美国参与制定全球标准。\n\nOpenAI随后发布“National Community Compact”和“Compute Campus Policy Blueprint”，称未来每个自建自营的计算园区都将有本地协议，承诺全额承担用电与所需基础设施成本、每年公开各站点水耗与用电数据、不使用保密协议限制公共官员，并建议州公用事业委员会要求大用电客户承担其新增电网成本。\n\n跟进报道补充，OpenAI还承诺在项目被砍时提供财务担保、公开噪音与招聘数据，并资助当地优先事项，例如佐治亚州480万美元的学校餐费补助。这些承诺适用于OpenAI自建自营的园区，并称将推动监管把规则扩展到所有开发商。","digestUpdatedAt":"2026-11-06T00:46:04.853Z","reports":[{"id":"v74el189fl1z6z01w1ncvf0m7","title":"OpenAI 宣布数据中心社区承诺，不再对公职人员使用 NDA","summary":"OpenAI 在中期选举选民表达反对数据中心扩建后宣布新的数据中心社区承诺，包括不再与公职人员签署保密协议（NDA），仅保留涉及安全信息、商业秘密或竞争敏感信息的窄幅保护。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-06T00:37:56.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1028454/openai-data-center-nda"},{"id":"pa4qeatsai3vfpr66bcp7wur6","title":"OpenAI 承诺自建数据中心承担全部电力与电网成本，并推动监管将规则扩展到所有开发商","summary":"OpenAI 宣布其拥有的未来数据中心园区将承担全部电力和电网成本，项目被砍时提供财务担保，公开水、电力、噪音和招聘数据，避免与官员签保密协议，并资助当地优先事项，包括佐治亚州 480 万美元的学校餐费补助。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-05T23:36:15.000Z","url":"https://x.com/rohanpaul_ai/status/2118487588571082829"},{"id":"to77pnxlc8v37c6ki5ccxzfkj","title":"OpenAI 公布负责任 AI 基建新承诺","summary":"承载 AI 基础设施的社区，应当对其建设方式拥有发言权，并共享其带来的收益。\n\n今天，我们宣布对所在社区的新承诺，以及关于负责任 AI 基础设施的政策建议。\n\nhttps://openai.com/index/setting-new-standard-responsible-ai-infrastructure/","sourceName":"X：OpenAI Newsroom (@OpenAINewsroom)","firstParty":false,"publishedAt":"2026-11-05T20:09:03.000Z","url":"https://x.com/OpenAINewsroom/status/2118435446913159514"},{"id":"aail7mpymwf26xpr6k46jdsod","title":"OpenAI 在中期选举失利后推出社区自愿承诺以推动 AI 基建扩张","summary":"OpenAI 发布国家社区公约和政策蓝图，承诺在自建数据站点不要求与地方当局签保密协议、承担全部电力和电网升级费用、高峰时段限电并公开施工、噪音和用水数据，并呼吁立法者将规则扩展到全行业。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-05T14:37:46.000Z","url":"https://the-decoder.com/after-midterm-rout-openai-tries-to-win-over-communities-it-needs-for-ai-expansion/"},{"id":"wqavndg3uamacnmzrdu4firue","title":"OpenAI 发布《国家社区契约》与《算力园区政策蓝图》，承诺自担供电成本并公开建设规划","summary":"面对全美对数据中心耗电、耗水及噪音的抵制，OpenAI 于 11 月 5 日发布《国家社区契约》与《算力园区政策蓝图》。承诺全额承担用电及电网扩容成本并设专项财务担保，不再要求地方公职人员签署保密协议，为每个园区制定水资源方案并公开耗电耗水与噪音评估，俄亥俄州南部设施预计带来 2,500 个岗位、平均年薪 8 万美元。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-05T11:04:59.287Z","url":"https://www.ithome.com/1/022/958.htm"},{"id":"ucjc4bgt94880kx1drc9czbqp","title":"OpenAI 发布 National Community Compact 与 Compute Campus Policy Blueprint","summary":"OpenAI 发布 National Community Compact 和 Compute Campus Policy Blueprint，为其自建自营的计算园区设定社区承诺，并提议政策确保社区在园区开发中有实质发言权。承诺包括全额承担用电与基础设施成本、发布各站点水耗与用电数据、不使用 NDA 限制公共官员，并公布就业与学徒数据。蓝图还建议州公用事业委员会要求大用电客户承担其新增电网成本。","sourceName":"OpenAI：官网动态（RSS · 排除企业/客户案例）","firstParty":true,"publishedAt":"2026-11-05T02:00:00.000Z","url":"https://openai.com/index/setting-new-standard-responsible-ai-infrastructure"},{"id":"hrxdnlymj2phbpvvohwdeezk1","title":"OpenAI 为中期选举后的华盛顿筹备游说攻势","summary":"据 Axios 报道，OpenAI 正在为美国中期选举后的政治游说和公关行动做准备，以防民主党赢得众议院多数后监管压力加大。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-02T10:47:59.000Z","url":"https://the-decoder.com/openai-prepares-lobbying-blitz-for-a-post-midterm-washington/"},{"id":"uvby5zm2ui9xmyn68hxjn1h2e","title":"OpenAI 将启动大规模公关宣传，考虑把数据中心重新包装为“AI 算力园区”","summary":"OpenAI 计划在周二美国中期选举结束后发起大规模公关宣传活动，首席全球事务官克里斯·莱汉称此次选举将成为 2028 年总统大选的“预告片”。OpenAI 还计划制定 AI 发展速度限制、推动美国参与全球标准制定，并将数据中心重新包装为“AI 算力园区”。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-01T22:58:19.947Z","url":"https://www.ithome.com/1/020/844.htm"},{"id":"apioobuo772gw6rynva9a573j","title":"OpenAI 或把数据中心改名为“AI 算力园区”","summary":"OpenAI 正筹备中期选举后的公关攻势，其首席全球事务官 Chris Lehane 提出将数据中心重新包装为“AI 算力园区”。他还提到推动设立 AI“限速”、让民众感受到 AI 对日常生活的赋能，并推动美国参与制定全球标准。Lehane 称围绕数据中心的争论“良性且健康”，社区应让企业承担责任。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-01T21:55:23.000Z","url":"https://techcrunch.com/2026/11/01/openai-might-rebrand-its-data-centers-as-ai-compute-campuses/"},{"id":"cr20os47n7rt4z16vt9w80w01","title":"OpenAI 将数据中心改称\"AI 算力园区\"","summary":"axios：OpenAI 将在中期选举后启动一项政策攻势，届时开始把其数据中心称为\"AI 算力园区\"。\n\n这一品牌重塑之际，数据中心正成为两党共同的包袱。\n\n为化解这种反对，OpenAI 将提供社区协议，并推动州级立法，让居民对项目的建设方式及所获收益拥有真正的发言权。\n\n这项攻势将在跛脚鸭会期启动，此时 AI 公司正面对一个更严苛的华盛顿——民主党很可能拿下众议院。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-01T20:13:13.000Z","url":"https://x.com/rohanpaul_ai/status/2116986944605606059"}]},"eb3a8a76-8af1-48fb-8fa0-67903c2b1174":{"publicId":"eb3a8a76-8af1-48fb-8fa0-67903c2b1174","title":"OpenAI宣布收购Pierre，工具将并入Codex","status":"active","sourceCount":6,"reportCount":6,"firstReportAt":"2026-11-04T14:30:00.000Z","latestAt":"2026-11-05T07:06:27.400Z","latest":"OpenAI 宣布收购 Pierre，计划将其功能整合进 Codex","digest":"OpenAI 宣布收购 Pierre Computer Company，即 Code Storage 及 Trees、Diffs、Highlights 等开源开发者工具背后的公司，以推进把 Codex 打造成团队与 AI 协同开发软件的平台。OpenAI 称，这些工具已用于 Codex 的部分功能，包括文件浏览、代码变更审阅和实时语法高亮。\n\n交割后 Pierre 的开源项目将继续开源，Code Storage 客户可继续使用，相关功能将逐步并入 Codex。交易金额未披露。\n\n交割尚待监管批准，在此之前两家公司保持独立。OpenAI 总裁 Greg Brockman 在社交平台发文“欢迎 Pierre 加入 OpenAI”，未说明具体计划。","digestUpdatedAt":"2026-11-05T07:42:53.873Z","reports":[{"id":"ejxw3mg0o7k5uqpvce1xzqs1g","title":"OpenAI 宣布收购 Pierre，计划将其功能整合进 Codex","summary":"OpenAI 于当地时间本月 4 日宣布收购 Pierre，该公司开发了 Code Storage 分布式存储系统，以及 Trees、Diffs 功能库和 Highlights 实时高亮工具，帮助开发者浏览、定位和审查大量代码。OpenAI 表示 Pierre 的开源项目将继续保持开源，客户可继续使用 Code Storage，OpenAI 将把其各项功能整合到 Codex 中。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-05T07:06:27.400Z","url":"https://www.ithome.com/1/022/758.htm"},{"id":"rq7es9q5vahm2cw48k2fseexf","title":"OpenAI 收购 Pierre Computer Company 以让 Git 适应 AI 编码智能体","summary":"OpenAI 宣布收购 Code Storage 背后的 Pierre Computer Company，其开源库已被 OpenAI 编码智能体 Codex 使用，包括快速文件导航工具 Trees、可在 diff 视图中直接修复 bug 的 Diffs 和实时语法高亮 Highlights。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-04T18:41:03.000Z","url":"https://the-decoder.com/openai-acquires-pierre-computer-company-to-make-git-keep-up-with-ai-coding-agents/"},{"id":"zich01p3hiskiuyapwskpveuj","title":"Pierre Computer 加入 OpenAI，其开源开发者工具已用于 Codex","summary":"OpenAI 总裁 Greg Brockman 宣布 @pierrecomputer（Pierre Computer Company）加入 OpenAI。Pierre 的开源开发者工具目前已支撑 Codex 的部分功能，双方将共同打造用 AI 协作构建软件的未来。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-04T18:05:50.000Z","url":"https://x.com/gdb/status/2118042051057250377"},{"id":"a6227loyev7nwpnawdacna3gz","title":"OpenAI 欢迎 Pierre 加入并预告重塑一切","summary":"计算机是有 RAM 的吧？\n\n欢迎 Pierre。让我们重塑一切","sourceName":"X：Tibo (@thsottiaux)","firstParty":true,"publishedAt":"2026-11-04T16:54:47.000Z","url":"https://x.com/thsottiaux/status/2118024169762029594"},{"id":"f3buned9irnzvhg9bfd59x0jt","title":"OpenAI 宣布收购 Pierre，加速把 Codex 打造成团队与 AI 协同的软件开发平台","summary":"OpenAI 官方宣布将收购 Pierre，以推进把 Codex 打造为团队与 AI 协同构建软件平台的规划。Pierre 的开源开发者工具目前已在 Codex 的部分功能中使用，双方将在这一基础上面向 agentic 时代继续开发。","sourceName":"X：OpenAI Newsroom (@OpenAINewsroom)","firstParty":false,"publishedAt":"2026-11-04T15:15:43.000Z","url":"https://x.com/OpenAINewsroom/status/2117999237745049883"},{"id":"c39s97tylya5njp0nro6dwvbx","title":"OpenAI 宣布收购 Code Storage 背后公司 Pierre","summary":"OpenAI 宣布收购 Pierre Computer Company，即 Code Storage 及多款开源开发者工具背后的公司。其 Trees 和 Diffs 库已被用于 Codex 应用的文件浏览与代码变更审阅；交割后 Pierre 的开源项目将继续开源，Code Storage 客户可继续使用，功能将逐步并入 Codex，交割尚待监管批准。","sourceName":"OpenAI：官网动态（RSS · 排除企业/客户案例）","firstParty":true,"publishedAt":"2026-11-04T14:30:00.000Z","url":"https://openai.com/index/openai-to-acquire-pierre"}]}}};
